-- Function: public.sp_get_user_accessible_branches
-- Backup generated on 2026-11-11 09:05:52

CREATE OR REPLACE PROCEDURE public.sp_get_user_accessible_branches(IN p_tenant_id uuid, IN p_user_id uuid, IN p_is_org_admin boolean, INOUT cur refcursor DEFAULT 'cur_accessible_branches'::refcursor)  LANGUAGE plpgsql AS $procedure$ BEGIN     OPEN cur FOR     WITH allowed_branches AS (         SELECT b.id AS branch_id         FROM branches b         JOIN organizations o ON b.organization_id = o.id         WHERE b.tenant_id = p_tenant_id           AND b.is_active = true           AND (               -- Org Admin can access all branches in tenant               p_is_org_admin = true               -- Branch Admin / Staff explicitly assigned               OR EXISTS (                   SELECT 1 FROM user_branch_assignments uba                   WHERE uba.user_id = p_user_id                     AND uba.branch_id = b.id                     AND uba.tenant_id = p_tenant_id                     AND uba.revoked_at IS NULL               )               -- Teachers assigned to classrooms in this branch               OR EXISTS (                   SELECT 1 FROM classroom_teachers ct                   JOIN classrooms cr ON ct.classroom_id = cr.id                   WHERE ct.user_id = p_user_id                     AND cr.branch_id = b.id                     AND cr.tenant_id = p_tenant_id               )               -- Fallback: Staff with employment in this branch               OR EXISTS (                   SELECT 1 FROM teachers t                   JOIN teacher_employments te ON t.id = te.teacher_id                   WHERE t.user_id = p_user_id                     AND te.branch_id = b.id                     AND t.tenant_id = p_tenant_id               )           )     )     SELECT          o.id AS organization_id,         o.name::VARCHAR(200) AS organization_name,         b.id AS branch_id,         b.name::VARCHAR(200) AS branch_name,         COALESCE(b.location, 'Main Campus')::VARCHAR(300) AS location,         EXISTS (             SELECT 1 FROM user_branch_assignments uba              WHERE uba.user_id = p_user_id AND uba.branch_id = b.id         ) AS is_primary     FROM branches b     JOIN organizations o ON b.organization_id = o.id     JOIN allowed_branches ab ON b.id = ab.branch_id     ORDER BY b.name; END; $procedure$ ;
